# -*- coding: utf-8 -*-
"""Этап 23 (v22.1): синхронизация документов пакета — корневой README,
итоговый README, инструкция, VERSIONS.md (пункт 32)."""
import io, os, re

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.join(HERE, '..')
OUT = os.path.join(ROOT, 'output')


def edit(path, pairs):
    p = os.path.join(ROOT, path) if not path.startswith('output') else os.path.join(ROOT, path)
    s = io.open(p, encoding='utf-8').read()
    for old, new, n in pairs:
        c = s.count(old)
        assert c == n, '%s: ANCHOR %d!=%d %r' % (path, c, n, old[:70])
        s = s.replace(old, new)
    assert not re.search(r'[\u4e00-\u9fff]', s), 'CJK ' + path
    io.open(p, 'w', encoding='utf-8').write(s)
    print('OK %-42s %d замен, %d байт' % (path, len(pairs), len(s.encode('utf-8'))))


